"use client";

import { Check, ChevronDown, CircleAlert, FileText, Search, Star, Upload, X } from "lucide-react";
import { Command } from "cmdk";
import { enUS } from "date-fns/locale";
import { DayPicker, type DateRange, type DayButtonProps } from "react-day-picker";
import ReactDatePicker from "react-datepicker";
import { EditorContent, useEditor } from "@tiptap/react";
import StarterKit from "@tiptap/starter-kit";
import { useRef, useState } from "react";
import { Button } from "@/app/components/ui/button";
import { Popover } from "@/app/components/ui/popover";

export type FormShowcaseKind = "form-control" | "input-group" | "select" | "checks" | "range" | "floating-labels" | "form-layout" | "advanced-select" | "date-picker" | "editor" | "file-uploader" | "advanced-range" | "rating" | "emoji-button" | "validation" | "wizard";

const meta: Record<FormShowcaseKind, { title: string; trail: string; description: string; section: string }> = {
  "form-control": { title: "Form control", trail: "Forms / Basic", section: "Form control", description: "Standard textual and contextual fields with consistent sizing, focus treatment, and helper text." },
  "input-group": { title: "Input group", trail: "Forms / Basic", section: "Input group", description: "Attach text, controls, and actions to either side of a form input." },
  select: { title: "Select", trail: "Forms / Basic", section: "Select", description: "Searchable cmdk selection controls with consistent visual treatment and visible focus states." },
  checks: { title: "Checks", trail: "Forms / Basic", section: "Checks", description: "Accessible checkboxes, radio groups, switches, and toggle controls." },
  range: { title: "Range", trail: "Forms / Basic", section: "Range", description: "Native range inputs with a clear value and accessible labels." },
  "floating-labels": { title: "Floating labels", trail: "Forms / Basic", section: "Floating labels", description: "Space-efficient labels that remain visible while people enter a value." },
  "form-layout": { title: "Layout", trail: "Forms / Basic", section: "Layout", description: "Responsive grids and label alignment patterns for complete forms." },
  "advanced-select": { title: "Advanced select", trail: "Forms / Advance", section: "Advanced select", description: "Searchable, grouped, and multiple-choice selection patterns." },
  "date-picker": { title: "Date picker", trail: "Forms / Advance", section: "Date picker", description: "Date, time, range, and human-friendly date-entry examples." },
  editor: { title: "Editor", trail: "Forms / Advance", section: "Editor", description: "A focused rich-text editing surface with a keyboard-friendly toolbar." },
  "file-uploader": { title: "File uploader", trail: "Forms / Advance", section: "File uploader", description: "File selection and drag-and-drop affordances with clear file constraints." },
  "advanced-range": { title: "Advanced range", trail: "Forms / Advance", section: "Advanced range", description: "Connected range values, steps, visual pips, and live output." },
  rating: { title: "Rating", trail: "Forms / Advance", section: "Rating", description: "Keyboard-operable rating controls with an explicit selected value." },
  "emoji-button": { title: "Emoji button", trail: "Forms / Advance", section: "Emoji button", description: "A small picker that inserts an emoji into adjacent text." },
  validation: { title: "Validation", trail: "Forms", section: "Validation", description: "Constraint validation with clear success, error, and recovery guidance." },
  wizard: { title: "Wizard", trail: "Forms", section: "Wizard", description: "A progressive, validated multi-step flow for longer submissions." },
};

function Card({ title, note, children, className = "" }: { title: string; note: string; children: React.ReactNode; className?: string }) { return <section className={`forms-showcase-card${className ? ` ${className}` : ""}`}><div className="forms-showcase-heading"><div><p className="card-kicker">Example</p><h2>{title}</h2></div><span>{note}</span></div>{children}</section>; }
const Field = ({ label, children, hint }: { label: string; children: React.ReactNode; hint?: string }) => <label className="forms-field"><span>{label}</span>{children}{hint ? <small>{hint}</small> : null}</label>;
const TextInput = (props: React.InputHTMLAttributes<HTMLInputElement>) => <input className="forms-input" {...props} />;
const FieldMessage = ({ id, show, children }: { id: string; show: boolean; children: React.ReactNode }) => show ? <small id={id} className="forms-error" role="alert">{children}</small> : null;
const parseDateValue = (value: string) => { const [year, month, day] = value.split("-").map(Number); if (!year || !month || !day) return null; const date = new Date(year, month - 1, day); return date.getFullYear() === year && date.getMonth() === month - 1 && date.getDate() === day ? date : null; };
const formatDateValue = (date: Date) => `${date.getFullYear()}-${String(date.getMonth() + 1).padStart(2, "0")}-${String(date.getDate()).padStart(2, "0")}`;
const parseMonthYearValue = (value: string) => { const [month, year] = value.split("/").map(Number); if (!month || !year) return null; return new Date(year, month - 1, 1); };
const formatMonthYearValue = (date: Date) => `${String(date.getMonth() + 1).padStart(2, "0")}/${date.getFullYear()}`;
const dragCalendarMonth = new Date(Date.UTC(2026, 7, 1));
const dragCalendarToday = new Date(Date.UTC(2026, 7, 10));
const dragDateFormatter = new Intl.DateTimeFormat("en-US", { timeZone: "UTC", month: "short", day: "numeric" });
const dragDateYearFormatter = new Intl.DateTimeFormat("en-US", { timeZone: "UTC", month: "short", day: "numeric", year: "numeric" });
const pickerStartMonth = new Date(Date.UTC(2020, 0, 1));
const pickerEndMonth = new Date(Date.UTC(2030, 11, 1));
const parseTimeValue = (value: string) => { const [hours, minutes] = value.split(":").map(Number); if (!Number.isInteger(hours) || !Number.isInteger(minutes) || hours < 0 || hours > 23 || minutes < 0 || minutes > 59) return null; return new Date(2026, 7, 10, hours, minutes); };
const formatTimeValue = (date: Date) => `${String(date.getHours()).padStart(2, "0")}:${String(date.getMinutes()).padStart(2, "0")}`;
const formatUtcDateInput = (date?: Date) => date ? `${date.getUTCFullYear()}-${String(date.getUTCMonth() + 1).padStart(2, "0")}-${String(date.getUTCDate()).padStart(2, "0")}` : "";
const parseUtcDateInput = (value: string) => { const match = /^(\d{4})-(\d{2})-(\d{2})$/.exec(value); if (!match) return null; const date = new Date(Date.UTC(Number(match[1]), Number(match[2]) - 1, Number(match[3]))); return date.getUTCFullYear() === Number(match[1]) && date.getUTCMonth() === Number(match[2]) - 1 && date.getUTCDate() === Number(match[3]) ? date : null; };
const monthStart = (date: Date) => new Date(Date.UTC(date.getUTCFullYear(), date.getUTCMonth(), 1));
const formatMonthInput = (date: Date) => `${date.getUTCFullYear()}-${String(date.getUTCMonth() + 1).padStart(2, "0")}`;
const parseMonthInput = (value: string) => { const match = /^(\d{4})-(\d{2})$/.exec(value); if (!match) return null; const date = new Date(Date.UTC(Number(match[1]), Number(match[2]) - 1, 1)); return date.getUTCFullYear() === Number(match[1]) && date.getUTCMonth() === Number(match[2]) - 1 ? date : null; };
function WizardDateField({ id, label, value, onChange, monthYear = false, invalid = false, describedBy, errorId, errorMessage }: { id: string; label: string; value: string; onChange: (value: string) => void; monthYear?: boolean; invalid?: boolean; describedBy?: string; errorId?: string; errorMessage?: string }) { const selected = monthYear ? parseMonthYearValue(value) : parseDateValue(value); return <label className="forms-field"><span>{label}</span><ReactDatePicker id={id} selected={selected} onChange={(date: Date | Date[] | null) => { const picked = Array.isArray(date) ? date[0] : date; onChange(picked ? (monthYear ? formatMonthYearValue(picked) : formatDateValue(picked)) : ""); }} showMonthYearPicker={monthYear} showFullMonthYearPicker={monthYear} showYearDropdown={!monthYear} dropdownMode="select" dateFormat={monthYear ? "MM/yyyy" : "MMM d, yyyy"} placeholderText={monthYear ? "MM/YYYY" : "Choose a date"} className={`forms-input forms-date-picker-input${invalid ? " forms-input--invalid" : ""}`} wrapperClassName="forms-date-picker" popperClassName="forms-date-picker-popper" aria-label={label} aria-invalid={invalid ? "true" : undefined} aria-describedby={describedBy} autoComplete="off" />{errorId && errorMessage ? <FieldMessage id={errorId} show={invalid}>{errorMessage}</FieldMessage> : null}</label>; }
function TimePickerField({ id, label, value, onChange }: { id: string; label: string; value: string; onChange: (value: string) => void }) {
  const handleChange = (date: Date | Date[] | null) => {
    const picked = Array.isArray(date) ? date[0] : date;
    onChange(picked ? formatTimeValue(picked) : "");
  };

  return <div className="forms-time-picker-field"><label className="forms-field" htmlFor={id}><span>{label}</span></label><div className="forms-time-picker-control"><ReactDatePicker id={id} selected={parseTimeValue(value)} onChange={handleChange} showTimeSelect showTimeSelectOnly timeIntervals={1} timeCaption="Time" timeFormat="HH:mm" dateFormat="HH:mm" placeholderText="Choose a time" className="forms-input forms-date-picker-input" wrapperClassName="forms-date-picker" popperClassName="forms-date-picker-popper forms-time-only-popper" aria-label={label} aria-describedby={`${id}-hint`} autoComplete="off" isClearable={false} />{value ? <button className="forms-time-picker-clear" type="button" onClick={() => onChange("")} aria-label="Clear reminder time"><X aria-hidden="true" /></button> : null}</div><small id={`${id}-hint`}>Choose a minute or type an exact time in the field.</small></div>;
}

function CalendarProps({ input, children }: { input: React.ReactNode; children: React.ReactNode }) { return <div className="forms-date-example">{input}<div className="forms-date-calendar">{children}</div></div>; }
function DateTextInput({ id, label, date, onDateChange }: { id: string; label: string; date?: Date; onDateChange: (date: Date | undefined) => void }) { const [draftState, setDraftState] = useState<{ date?: Date; value: string }>({ date, value: formatUtcDateInput(date) }); const draft = draftState.date === date ? draftState.value : formatUtcDateInput(date); const commit = () => { const parsed = parseUtcDateInput(draft); if (parsed) onDateChange(parsed); else setDraftState({ date, value: formatUtcDateInput(date) }); }; return <label className="forms-field"><span>{label}</span><input id={id} className="forms-input" type="text" inputMode="numeric" value={draft} placeholder="YYYY-MM-DD" onChange={(event) => setDraftState({ date, value: event.target.value })} onBlur={commit} onKeyDown={(event) => { if (event.key === "Enter") { event.preventDefault(); commit(); } }} aria-label={label} /></label>; }
function PickerMonthInput({ id, label, date, onDateChange, yearOnly = false }: { id: string; label: string; date: Date; onDateChange: (date: Date) => void; yearOnly?: boolean }) { return <label className="forms-field"><span>{label}</span><input id={id} className="forms-input" type={yearOnly ? "number" : "month"} min={yearOnly ? "2020" : "2020-01"} max={yearOnly ? "2030" : "2030-12"} value={yearOnly ? String(date.getUTCFullYear()) : formatMonthInput(date)} onChange={(event) => { if (yearOnly) { const year = Number(event.target.value); if (year >= 2020 && year <= 2030) onDateChange(new Date(Date.UTC(year, date.getUTCMonth(), 1))); } else { const parsed = parseMonthInput(event.target.value); if (parsed) onDateChange(parsed); } }} aria-label={label} /></label>; }
function SingleDateExample() { const [date, setDate] = useState<Date | undefined>(new Date(Date.UTC(2026, 7, 8))); const [month, setMonth] = useState(dragCalendarMonth); const handleDateChange = (next?: Date) => { setDate(next); if (next) setMonth(monthStart(next)); }; return <CalendarProps input={<DateTextInput id="forms-start-date" label="Start date" date={date} onDateChange={handleDateChange} />}><p className="forms-hint">Selected: <b>{date ? dragDateYearFormatter.format(date) : "Choose a date"}</b></p><DayPicker mode="single" month={month} onMonthChange={setMonth} today={dragCalendarToday} timeZone="UTC" locale={enUS} selected={date} onSelect={handleDateChange} showOutsideDays aria-label="Start date calendar" /></CalendarProps>; }
function DateTimeExample() { const [date, setDate] = useState<Date | undefined>(new Date(Date.UTC(2026, 7, 8))); const [month, setMonth] = useState(dragCalendarMonth); const [time, setTime] = useState("09:30"); const handleDateChange = (next?: Date) => { setDate(next); if (next) setMonth(monthStart(next)); }; return <CalendarProps input={<DateTextInput id="forms-publish-date" label="Publish date" date={date} onDateChange={handleDateChange} />}><p className="forms-hint">Selected: <b>{date ? `${dragDateYearFormatter.format(date)} at ${time}` : "Choose a date and time"}</b></p><DayPicker mode="single" month={month} onMonthChange={setMonth} today={dragCalendarToday} timeZone="UTC" locale={enUS} selected={date} onSelect={handleDateChange} showOutsideDays aria-label="Publish date calendar" /><label className="forms-field"><span>Publish time</span><input className="forms-input" type="time" step="60" value={time} onChange={(event) => setTime(event.target.value)} /></label></CalendarProps>; }
function DateRangeExample() { const [range, setRange] = useState<DateRange>({ from: new Date(Date.UTC(2026, 7, 10)), to: new Date(Date.UTC(2026, 7, 14)) }); const [month, setMonth] = useState(dragCalendarMonth); const handleRangeChange = (value: DateRange | undefined) => { setRange(value ?? { from: undefined, to: undefined }); if (value?.from) setMonth(monthStart(value.from)); }; return <CalendarProps input={<div className="forms-date-input-grid"><DateTextInput id="forms-range-start" label="From" date={range.from} onDateChange={(from) => handleRangeChange({ from, to: range.to })} /><DateTextInput id="forms-range-end" label="To" date={range.to} onDateChange={(to) => handleRangeChange({ from: range.from, to })} /></div>}><p className="forms-hint">Selected: <b>{range.from && range.to ? `${dragDateFormatter.format(range.from)} – ${dragDateYearFormatter.format(range.to)}` : "Choose a date range"}</b></p><DayPicker mode="range" month={month} onMonthChange={setMonth} today={dragCalendarToday} timeZone="UTC" locale={enUS} selected={range} onSelect={handleRangeChange} showOutsideDays aria-label="Date range calendar" /></CalendarProps>; }

function DragDateRangePicker() {
  const [range, setRange] = useState<DateRange>({ from: dragCalendarToday, to: new Date(Date.UTC(2026, 7, 14)) });
  const [month, setMonth] = useState(dragCalendarMonth);
  const [isDragging, setIsDragging] = useState(false);
  const dragStart = useRef<Date | undefined>(undefined);
  const suppressNextClick = useRef(false);
  const formatRange = (value: DateRange) => value.from && value.to ? `${dragDateFormatter.format(value.from)} – ${dragDateYearFormatter.format(value.to)}` : value.from ? `Starting ${dragDateYearFormatter.format(value.from)}` : "Choose a date range";
  const setDragRange = (date: Date) => {
    const from = dragStart.current;
    if (!from) return;
    setRange(from <= date ? { from, to: date } : { from: date, to: from });
  };
  const DragDayButton = ({ day, modifiers, onClick, onPointerDown, onPointerEnter, onPointerUp, ...buttonProps }: DayButtonProps) => { void modifiers; return <button {...buttonProps} onPointerDown={(event) => { onPointerDown?.(event); if (event.button !== 0) return; dragStart.current = day.date; suppressNextClick.current = true; setRange({ from: day.date, to: day.date }); setIsDragging(true); }} onPointerEnter={(event) => { onPointerEnter?.(event); if (dragStart.current) setDragRange(day.date); }} onPointerUp={(event) => { onPointerUp?.(event); if (dragStart.current) setDragRange(day.date); setIsDragging(false); }} onClick={(event) => { if (suppressNextClick.current) { event.preventDefault(); suppressNextClick.current = false; dragStart.current = undefined; return; } onClick?.(event); }} />; };
  const handleRangeChange = (value: DateRange | undefined) => { setRange(value ?? { from: undefined, to: undefined }); if (value?.from) setMonth(monthStart(value.from)); };
  return <div className="forms-date-example"><div className="forms-date-input-grid"><DateTextInput id="forms-drag-start" label="From" date={range.from} onDateChange={(from) => handleRangeChange({ from, to: range.to })} /><DateTextInput id="forms-drag-end" label="To" date={range.to} onDateChange={(to) => handleRangeChange({ from: range.from, to })} /></div><div className="forms-drag-date-picker" onPointerLeave={() => setIsDragging(false)}><p id="forms-drag-date-instructions" className="forms-hint">Drag across dates to select a range. You can also choose the start and end date with the keyboard.</p><DayPicker mode="range" month={month} onMonthChange={setMonth} today={dragCalendarToday} timeZone="UTC" locale={enUS} selected={range} onSelect={handleRangeChange} showOutsideDays fixedWeeks components={{ DayButton: DragDayButton }} aria-describedby="forms-drag-date-instructions" /><output className="forms-drag-date-output" aria-live="polite">{isDragging ? "Selecting: " : "Selected: "}{formatRange(range)}</output></div></div>;
}

function MonthPickerExample() { const [month, setMonth] = useState(dragCalendarMonth); const selectMonth = (date: Date) => setMonth(monthStart(date)); return <CalendarProps input={<PickerMonthInput id="forms-month-picker" label="Month" date={month} onDateChange={selectMonth} />}><p className="forms-hint">Selected month: <b>{dragDateYearFormatter.format(month)}</b></p><DayPicker mode="single" month={month} onMonthChange={selectMonth} selected={month} onSelect={(date) => date && selectMonth(date)} startMonth={pickerStartMonth} endMonth={pickerEndMonth} captionLayout="dropdown-months" timeZone="UTC" locale={enUS} showOutsideDays aria-label="Month picker calendar" /></CalendarProps>; }
function YearPickerExample() { const [year, setYear] = useState(dragCalendarMonth); const selectYear = (date: Date) => setYear(new Date(Date.UTC(date.getUTCFullYear(), year.getUTCMonth(), 1))); return <CalendarProps input={<PickerMonthInput id="forms-year-picker" label="Year" date={year} onDateChange={selectYear} yearOnly />}><p className="forms-hint">Selected year: <b>{year.getUTCFullYear()}</b></p><DayPicker mode="single" month={year} onMonthChange={selectYear} selected={year} onSelect={(date) => date && selectYear(date)} startMonth={pickerStartMonth} endMonth={pickerEndMonth} captionLayout="dropdown-years" timeZone="UTC" locale={enUS} showOutsideDays aria-label="Year picker calendar" /></CalendarProps>; }
function MonthYearPickerExample() { const [monthYear, setMonthYear] = useState(dragCalendarMonth); const selectMonthYear = (date: Date) => setMonthYear(monthStart(date)); return <CalendarProps input={<PickerMonthInput id="forms-month-year-picker" label="Month and year" date={monthYear} onDateChange={selectMonthYear} />}><p className="forms-hint">Selected: <b>{dragDateYearFormatter.format(monthYear)}</b></p><DayPicker mode="single" month={monthYear} onMonthChange={selectMonthYear} selected={monthYear} onSelect={(date) => date && selectMonthYear(date)} startMonth={pickerStartMonth} endMonth={pickerEndMonth} captionLayout="dropdown" timeZone="UTC" locale={enUS} showOutsideDays aria-label="Month and year picker calendar" /></CalendarProps>; }

function FormControl() { return <div className="forms-showcase-grid"><Card title="Basic Example" note="Text input"><Field label="Workspace name" hint="Use a name your team recognizes."><TextInput placeholder="YoruSpace" /></Field></Card><Card title="Text area" note="Multiline"><Field label="Message"><textarea className="forms-input" rows={4} aria-label="Message" placeholder="Write a short update for your team" /></Field></Card><Card title="Sizing" note="Large + small"><div className="forms-stack"><TextInput className="forms-input forms-input--lg" placeholder="Large control" /><TextInput className="forms-input forms-input--sm" placeholder="Small control" /></div></Card><Card title="States" note="Disabled + readonly"><div className="forms-stack"><TextInput defaultValue="Unavailable" disabled /><TextInput defaultValue="Read-only workspace ID" readOnly /><p className="forms-plain-text">Read-only plain text: <b>team-yoru-108</b></p></div></Card><Card title="Files and color" note="Native inputs"><div className="forms-stack"><Field label="Attach a brief"><TextInput type="file" /></Field><Field label="Accent color"><div className="forms-accent-color-control"><span className="forms-accent-color-preview" aria-hidden="true" /><TextInput className="forms-accent-color" type="color" defaultValue="#5638df" aria-label="Accent color token" /></div></Field></div></Card></div>; }
function InputGroup() {
  const [inviteEmail, setInviteEmail] = useState("");
  const [invitedEmails, setInvitedEmails] = useState<string[]>([]);
  const [inviteMessage, setInviteMessage] = useState("");
  const [handle, setHandle] = useState("");
  const [handles, setHandles] = useState<string[]>([]);

  const addInvite = (event: React.FormEvent<HTMLFormElement>) => {
    event.preventDefault();
    const value = inviteEmail.trim();
    if (!value || !value.includes("@")) {
      setInviteMessage("Enter a valid email address to add an invite.");
      return;
    }
    if (invitedEmails.includes(value)) {
      setInviteMessage("That invite is already in the list.");
      return;
    }
    setInvitedEmails((current) => [...current, value]);
    setInviteEmail("");
    setInviteMessage(`${value} added to the invite list.`);
  };

  const addHandle = () => {
    const value = handle.trim().replace(/^@+/, "");
    if (!value || handles.includes(value)) return;
    setHandles((current) => [...current, value]);
    setHandle("");
  };

  return <div className="forms-showcase-grid">
    <Card title="Basic example" note="Prefix + suffix"><div className="forms-input-group"><span>https://</span><TextInput aria-label="Project URL" defaultValue="yoruspace.co" /><span>.com</span></div></Card>
    <Card title="Wrapping" note="Long content"><form className="forms-input-group forms-input-group--wrap" aria-label="Add invite" noValidate onSubmit={addInvite}><span>Invite</span><TextInput type="email" value={inviteEmail} onChange={(event) => setInviteEmail(event.target.value)} aria-label="Invite email" placeholder="name@company.com" /><Button size="sm" type="submit">Add</Button></form>{inviteMessage ? <p className="forms-input-group-feedback" aria-live="polite">{inviteMessage}</p> : null}{invitedEmails.length > 0 ? <ul className="forms-input-group-results" aria-label="Added invites">{invitedEmails.map((email) => <li key={email}>{email}</li>)}</ul> : null}</Card>
    <Card title="Check addons" note="Checkbox + radio"><div className="forms-stack"><div className="forms-input-group"><label><input type="checkbox" defaultChecked aria-label="Include name" /></label><TextInput aria-label="Name" placeholder="Name" /></div><div className="forms-input-group"><label><input type="radio" name="group-radio" defaultChecked aria-label="Primary" /></label><TextInput aria-label="Role" placeholder="Role" /></div></div></Card>
    <Card title="Multiple addons" note="Actions"><div className="forms-input-group"><Button appearance="subtle" size="sm">@</Button><TextInput aria-label="Handle" value={handle} onChange={(event) => setHandle(event.target.value)} placeholder="Handle" /><Button size="sm" onClick={addHandle} iconRight={<ChevronDown aria-hidden="true" />}>Add</Button></div>{handles.length > 0 ? <ul className="forms-input-group-results" aria-label="Added handles">{handles.map((item) => <li key={item}>@{item}</li>)}</ul> : null}</Card>
  </div>;
}
type CommandOption = { label: string; value: string };
type CommandOptionGroup = { heading: string; options: CommandOption[] };

function CommandItems({ options, selectedValue, selectedValues, onSelect }: { options: CommandOption[]; selectedValue?: string; selectedValues?: string[]; onSelect: (value: string) => void }) {
  return options.map((option) => {
    const selected = option.value !== "" && (selectedValues ? selectedValues.includes(option.value) : option.value === selectedValue);
    return <Command.Item key={option.value} value={option.value} aria-selected={selected} onSelect={() => onSelect(option.value)}><span>{option.label}</span>{selected ? <Check aria-hidden="true" /> : null}</Command.Item>;
  });
}

function CommandSelect({ ariaLabel, options, groups, value: selectedValue, onChange, placeholder = "Choose an option", size = "default", disabled = false, invalid = false, describedBy }: { ariaLabel: string; options: CommandOption[]; groups?: CommandOptionGroup[]; value: string; onChange: (value: string) => void; placeholder?: string; size?: "default" | "lg" | "sm"; disabled?: boolean; invalid?: boolean; describedBy?: string }) {
  const [open, setOpen] = useState(false);
  const listId = `forms-command-list-${ariaLabel.toLowerCase().replace(/[^a-z0-9]+/g, "-")}`;
  const selected = options.find((option) => option.value === selectedValue);
  const renderOptions = () => groups?.length ? groups.map((group) => <Command.Group key={group.heading} heading={group.heading}><CommandItems options={group.options} selectedValue={selectedValue} onSelect={(value) => { onChange(value); setOpen(false); }} /></Command.Group>) : <CommandItems options={options} selectedValue={selectedValue} onSelect={(value) => { onChange(value); setOpen(false); }} />;
  return <div className={`forms-command-select forms-command-select--${size}${invalid ? " forms-command-select--invalid" : ""}`} data-invalid={invalid || undefined}>
    <button className="forms-command-select-trigger" type="button" aria-label={ariaLabel} aria-haspopup="listbox" aria-expanded={open} aria-controls={open ? listId : undefined} aria-describedby={describedBy} disabled={disabled} onClick={() => setOpen((current) => !current)}><span>{selected?.label ?? placeholder}</span><ChevronDown aria-hidden="true" /></button>
    {open ? <div className="forms-command-select-menu" id={listId}><Command loop label={ariaLabel} onKeyDown={(event) => { if (event.key === "Escape") { event.preventDefault(); setOpen(false); } }}><div className="forms-command-input"><Search aria-hidden="true" /><Command.Input aria-label={`Search ${ariaLabel.toLowerCase()}`} placeholder={`Search ${ariaLabel.toLowerCase()}`} /></div><Command.List><Command.Empty>No matching options.</Command.Empty>{renderOptions()}</Command.List></Command></div> : null}
  </div>;
}

function CommandMultiSelect({ ariaLabel, options, values, onChange, placeholder = "Choose options" }: { ariaLabel: string; options: CommandOption[]; values: string[]; onChange: (values: string[]) => void; placeholder?: string }) {
  const [open, setOpen] = useState(false);
  const listId = `forms-command-list-${ariaLabel.toLowerCase().replace(/[^a-z0-9]+/g, "-")}`;
  const selectedLabels = options.filter((option) => values.includes(option.value)).map((option) => option.label);
  const toggleValue = (value: string) => onChange(values.includes(value) ? values.filter((item) => item !== value) : [...values, value]);
  return <div className="forms-command-select">
    <button className="forms-command-select-trigger" type="button" aria-label={ariaLabel} aria-haspopup="listbox" aria-expanded={open} aria-controls={open ? listId : undefined} onClick={() => setOpen((current) => !current)}><span>{selectedLabels.length > 0 ? selectedLabels.join(", ") : placeholder}</span><ChevronDown aria-hidden="true" /></button>
    {open ? <div className="forms-command-select-menu" id={listId}><Command loop label={ariaLabel} onKeyDown={(event) => { if (event.key === "Escape") { event.preventDefault(); setOpen(false); } }}><div className="forms-command-input"><Search aria-hidden="true" /><Command.Input aria-label={`Search ${ariaLabel.toLowerCase()}`} placeholder={`Search ${ariaLabel.toLowerCase()}`} /></div><Command.List><Command.Empty>No matching options.</Command.Empty><CommandItems options={options} selectedValues={values} onSelect={toggleValue} /></Command.List></Command></div> : null}
  </div>;
}

