function AdvancedSelect() { const choices: CommandOption[] = [{ label: "Design", value: "design" }, { label: "Engineering", value: "engineering" }, { label: "Marketing", value: "marketing" }]; const workspaceOptions: CommandOption[] = [{ label: "Design systems", value: "design-systems" }, { label: "Engineering", value: "engineering" }, { label: "Marketing", value: "marketing" }]; const optionGroups: CommandOptionGroup[] = [{ heading: "Product", options: choices.slice(0, 2) }, { heading: "Growth", options: [choices[2]] }]; const [selected, setSelected] = useState<string[]>(["design"]); const [workspace, setWorkspace] = useState("design-systems"); const [grouped, setGrouped] = useState("design"); const selectedItems = choices.filter((choice) => selected.includes(choice.value)); return <div className="forms-showcase-grid"><Card title="Single select with search" note="Cmdk combobox"><Field label="Workspace type"><CommandSelect ariaLabel="Workspace type" options={workspaceOptions} value={workspace} onChange={setWorkspace} /></Field><p className="forms-plain-text">Selected: <b>{workspaceOptions.find((option) => option.value === workspace)?.label}</b></p></Card><Card title="Multiple select with tags" note="Cmdk + tags"><div className="forms-tags" aria-label="Selected workspace areas">{selectedItems.map((item) => <button type="button" key={item.value} aria-label={`Remove ${item.label}`} onClick={() => setSelected((current) => current.filter((value) => value !== item.value))}>{item.label} ×</button>)}</div><CommandMultiSelect ariaLabel="Workspace areas" options={choices} values={selected} onChange={setSelected} /></Card><Card title="Option groups" note="Grouped cmdk"><Field label="Workspace category"><CommandSelect ariaLabel="Workspace category" options={optionGroups.flatMap((group) => group.options)} groups={optionGroups} value={grouped} onChange={setGrouped} /></Field></Card><Card title="Validation states" note="Feedback"><Field label="Workspace"><TextInput defaultValue="YoruSpace" aria-invalid="false" /><small className="forms-success">Looks good.</small></Field></Card></div>; }
