function EditorToolbar({ editor }: { editor: ReturnType<typeof useEditor> | null }) {
  const [linkOpen, setLinkOpen] = useState(false);
  const [linkUrl, setLinkUrl] = useState("");

  if (!editor) return null;

  const openLinkPopover = () => {
    setLinkUrl(editor.getAttributes("link").href ?? "");
    setLinkOpen(true);
  };

  const applyLink = (event: React.FormEvent<HTMLFormElement>) => {
    event.preventDefault();
    const href = linkUrl.trim();
    if (href) {
      editor.chain().focus().extendMarkRange("link").setLink({ href }).run();
    } else {
      editor.chain().focus().unsetLink().run();
    }
    setLinkOpen(false);
  };

  return <div className="forms-editor-toolbar" role="toolbar" aria-label="Text formatting">
    <Button type="button" size="sm" appearance={editor.isActive("bold") ? "solid" : "subtle"} aria-label="Bold" aria-pressed={editor.isActive("bold")} onClick={() => editor.chain().focus().toggleBold().run()}><b>B</b></Button>
    <Button type="button" size="sm" appearance={editor.isActive("italic") ? "solid" : "subtle"} aria-label="Italic" aria-pressed={editor.isActive("italic")} onClick={() => editor.chain().focus().toggleItalic().run()}><i>I</i></Button>
    <Popover className="forms-editor-link-popover" open={linkOpen} onOpenChange={setLinkOpen} trigger={<Button type="button" size="sm" appearance={editor.isActive("link") ? "solid" : "subtle"} aria-label="Add link" aria-pressed={editor.isActive("link")} onClick={openLinkPopover}>Link</Button>} title="Add a link" ariaLabel="Add a link">
      <form className="forms-editor-link-form" onSubmit={applyLink}>
        <label className="forms-field"><span>URL</span><input className="forms-input" type="url" value={linkUrl} onChange={(event) => setLinkUrl(event.target.value)} placeholder="https://example.com" /></label>
        <div className="forms-editor-link-actions"><Button type="submit" size="sm">Apply link</Button>{editor.isActive("link") ? <Button type="button" size="sm" appearance="outline" onClick={() => { editor.chain().focus().unsetLink().run(); setLinkOpen(false); }}>Remove</Button> : null}</div>
      </form>
    </Popover>
  </div>;
}

function TiptapEditor({ ariaLabel, compact = false }: { ariaLabel: string; compact?: boolean }) {
  const editor = useEditor({
    extensions: [StarterKit],
    content: compact ? "<p>Click here to edit this brief inline.</p>" : "<p>Draft a clear update for the team.</p>",
    immediatelyRender: false,
    editorProps: {
      attributes: {
        "aria-label": ariaLabel,
        class: compact ? "forms-inline-editor-content" : "forms-editor-content",
      },
    },
  });

  if (compact) return <div className="forms-inline-editor"><EditorContent editor={editor} /></div>;
  return <div className="forms-editor"><EditorToolbar editor={editor} /><EditorContent editor={editor} /></div>;
}

