function FileUploader() { const [files, setFiles] = useState<string[]>([]); return <div className="forms-showcase-grid"><Card title="Basic drag-and-drop example" note="One file"><label className="forms-dropzone"><Upload aria-hidden="true" /><b>Drop a file here or browse</b><span>PDF, PNG, or JPG up to 10MB</span><input type="file" onChange={(event) => setFiles(event.target.files ? Array.from(event.target.files).map((file) => file.name) : [])} /></label>{files[0] ? <p className="forms-success"><Check aria-hidden="true" /> {files[0]} ready to upload</p> : null}</Card><Card title="Multiple files" note="Several files"><label className="forms-dropzone"><FileText aria-hidden="true" /><b>Select documents</b><input type="file" multiple onChange={(event) => setFiles(event.target.files ? Array.from(event.target.files).map((file) => file.name) : [])} /></label><ul className="forms-file-list">{files.map((file) => <li key={file}>{file}</li>)}</ul></Card><Card title="Validation limits" note="File size"><p className="forms-plain-text"><CircleAlert aria-hidden="true" /> Files larger than 10MB are rejected before upload.</p></Card></div>; }
