function EmojiButton() { const [value, setValue] = useState(""); const [open, setOpen] = useState(false); const emojis = ["✨", "🎯", "👏", "🚀"]; return <div className="forms-showcase-grid"><Card title="Basic setup" note="Insert emoji"><div className="forms-emoji-control"><TextInput value={value} onChange={(event) => setValue(event.target.value)} placeholder="Write a note" /><Button type="button" appearance="subtle" onClick={() => setOpen((current) => !current)} aria-expanded={open} aria-label="Choose an emoji">☺</Button>{open ? <div className="forms-emoji-menu" role="menu">{emojis.map((emoji) => <button key={emoji} type="button" onClick={() => { setValue((current) => `${current}${emoji}`); setOpen(false); }}>{emoji}</button>)}</div> : null}</div></Card><Card title="Custom placement" note="Compact trigger"><p className="forms-plain-text">Emoji picker can be placed beside any text field or editor control.</p></Card></div>; }
function Validation() {
  const [values, setValues] = useState({ firstName: "Mark", lastName: "Otto", username: "", city: "", state: "", zip: "", terms: false });
  const [submitted, setSubmitted] = useState(false);
  const [success, setSuccess] = useState(false);
  const errors = { firstName: !values.firstName.trim(), lastName: !values.lastName.trim(), username: !values.username.trim(), city: !values.city.trim(), state: !values.state, zip: !/^\d{5}$/.test(values.zip), terms: !values.terms };
  const isInvalid = (field: keyof typeof errors) => submitted && errors[field];
  const update = <Key extends keyof typeof values>(key: Key, value: typeof values[Key]) => { setValues((current) => ({ ...current, [key]: value })); setSuccess(false); };
  const handleSubmit = (event: React.FormEvent<HTMLFormElement>) => { event.preventDefault(); setSubmitted(true); if (!Object.values(errors).some(Boolean)) setSuccess(true); };
  return <div className="forms-showcase-grid">
    <Card title="Custom styles validation" note="Inline feedback" className="forms-showcase-card--wide"><form className="forms-validation-form" noValidate onSubmit={handleSubmit}>
      <div className="forms-validation-grid">
        <Field label="First name"><TextInput id="validation-first-name" value={values.firstName} onChange={(event) => update("firstName", event.target.value)} required aria-invalid={isInvalid("firstName")} aria-describedby="validation-first-name-message" /><FieldMessage id="validation-first-name-message" show={isInvalid("firstName")} >Please provide your first name.</FieldMessage>{submitted && !errors.firstName ? <small className="forms-success">Looks good.</small> : null}</Field>
        <Field label="Last name"><TextInput id="validation-last-name" value={values.lastName} onChange={(event) => update("lastName", event.target.value)} required aria-invalid={isInvalid("lastName")} aria-describedby="validation-last-name-message" /><FieldMessage id="validation-last-name-message" show={isInvalid("lastName")}>Please provide your last name.</FieldMessage>{submitted && !errors.lastName ? <small className="forms-success">Looks good.</small> : null}</Field>
        <Field label="Username"><div className={`forms-input-group${isInvalid("username") ? " forms-input-group--invalid" : ""}`}><span aria-hidden="true">@</span><TextInput id="validation-username" value={values.username} onChange={(event) => update("username", event.target.value)} required aria-invalid={isInvalid("username")} aria-describedby="validation-username-message" /></div><FieldMessage id="validation-username-message" show={isInvalid("username")}>Please choose a username.</FieldMessage></Field>
        <Field label="City"><TextInput id="validation-city" value={values.city} onChange={(event) => update("city", event.target.value)} required aria-invalid={isInvalid("city")} aria-describedby="validation-city-message" /><FieldMessage id="validation-city-message" show={isInvalid("city")}>Please provide a valid city.</FieldMessage></Field>
        <Field label="State"><CommandSelect ariaLabel="State" options={[{ label: "Choose a state", value: "" }, { label: "California", value: "california" }, { label: "New York", value: "new-york" }, { label: "Texas", value: "texas" }]} value={values.state} onChange={(value) => update("state", value)} invalid={isInvalid("state")} describedBy="validation-state-message" /><FieldMessage id="validation-state-message" show={isInvalid("state")}>Please select a valid state.</FieldMessage></Field>
        <Field label="Zip"><TextInput id="validation-zip" inputMode="numeric" value={values.zip} onChange={(event) => update("zip", event.target.value)} required aria-invalid={isInvalid("zip")} aria-describedby="validation-zip-message" /><FieldMessage id="validation-zip-message" show={isInvalid("zip")}>Please provide a valid five-digit zip.</FieldMessage></Field>
      </div>
      <div><label className="forms-validation-check"><input type="checkbox" checked={values.terms} onChange={(event) => update("terms", event.target.checked)} aria-invalid={isInvalid("terms")} aria-describedby="validation-terms-message" /><span>I agree to the terms and privacy policy.</span></label><FieldMessage id="validation-terms-message" show={isInvalid("terms")}>You must agree before submitting.</FieldMessage></div>
      <div className="forms-validation-actions"><Button type="submit">Submit form</Button>{success ? <p className="forms-success" role="status" aria-live="polite"><Check aria-hidden="true" /> Everything looks good.</p> : null}</div>
    </form></Card>
    <Card title="Browser default validation" note="Required fields"><form className="forms-validation-simple-form"><Field label="Email"><TextInput type="email" required placeholder="name@company.com" /></Field><Field label="Project code"><TextInput required placeholder="YS-2048" /></Field><Button type="submit" appearance="outline">Submit</Button></form></Card>
    <Card title="Validation tooltips" note="Contextual feedback"><div className="forms-validation-tooltip"><Field label="Workspace slug"><TextInput defaultValue="yoru space" aria-invalid="true" /><small className="forms-error">Use lowercase letters, numbers, and hyphens.</small></Field></div><p className="forms-plain-text">Keep feedback close to the field so recovery is immediate.</p></Card>
    <Card title="Supported states" note="Success + error"><Field label="Validated workspace"><TextInput defaultValue="YoruSpace" aria-invalid="false" /><small className="forms-success">Looks good.</small></Field><Field label="Invalid field"><TextInput aria-invalid="true" defaultValue="" /><small className="forms-error">This field is required.</small></Field></Card>
  </div>;
}

function WizardProgress({ steps, currentStep, ariaLabel, onStepChange }: { steps: string[]; currentStep: number; ariaLabel: string; onStepChange?: (step: number) => void }) {
  return <ol className="forms-wizard-progress-bar" role="tablist" aria-label={ariaLabel}>
    {steps.map((label, index) => {
      const stepNumber = index + 1;
      const complete = stepNumber < currentStep;
      const current = stepNumber === currentStep;
      const disabled = stepNumber > currentStep || !onStepChange;
      return <li key={label} className={`${complete ? "is-complete " : ""}${current ? "is-current" : ""}`}>
        <button type="button" role="tab" className="forms-wizard-progress-bar-step" aria-selected={current} aria-current={current ? "step" : undefined} disabled={disabled} onClick={() => onStepChange?.(stepNumber)}>
          <span className="forms-wizard-progress-bar-node">{complete ? <Check aria-hidden="true" /> : stepNumber}</span>
          <span className="forms-wizard-progress-bar-label">{label}</span>
        </button>
        {index < steps.length - 1 ? <span className={`forms-wizard-progress-bar-line${complete ? " is-complete" : ""}`} aria-hidden="true" /> : null}
      </li>;
    })}
  </ol>;
}

function Wizard() {
  const steps = ["Account", "Personal", "Billing", "Done"];
  const [step, setStep] = useState(1);
  const [submitted, setSubmitted] = useState(false);
  const [values, setValues] = useState({ name: "", email: "", password: "", confirmPassword: "", terms: false, gender: "", phone: "", dateOfBirth: "", address: "", cardNumber: "", cardName: "", country: "", zip: "", expiration: "", cvv: "" });
  const update = <Key extends keyof typeof values>(key: Key, value: typeof values[Key]) => setValues((current) => ({ ...current, [key]: value }));
  const errors: Record<string, boolean> = step === 1 ? { name: !values.name.trim(), email: !/^[^\s@]+@[^\s@]+\.[^\s@]+$/.test(values.email), password: values.password.length < 8, confirmPassword: !values.confirmPassword || values.confirmPassword !== values.password, terms: !values.terms } : step === 2 ? { gender: !values.gender, phone: !values.phone.trim(), dateOfBirth: !values.dateOfBirth, address: !values.address.trim() } : step === 3 ? { cardNumber: values.cardNumber.replace(/\s/g, "").length < 12, cardName: !values.cardName.trim(), country: !values.country, zip: !/^\d{5}$/.test(values.zip), expiration: !/^\d{2}\/\d{4}$/.test(values.expiration), cvv: !/^\d{3,4}$/.test(values.cvv) } : {};
  const isInvalid = (field: string) => submitted && errors[field];
  const handleNext = (event: React.FormEvent<HTMLFormElement>) => { event.preventDefault(); if (step === 4) return; setSubmitted(true); if (Object.values(errors).some(Boolean)) return; setStep((current) => Math.min(4, current + 1)); setSubmitted(false); };
  const handleBack = () => { setStep((current) => Math.max(1, current - 1)); setSubmitted(false); };
  const goToStep = (target: number) => { if (target < step) { setStep(target); setSubmitted(false); } };
  const reset = () => { setStep(1); setSubmitted(false); setValues({ name: "", email: "", password: "", confirmPassword: "", terms: false, gender: "", phone: "", dateOfBirth: "", address: "", cardNumber: "", cardName: "", country: "", zip: "", expiration: "", cvv: "" }); };
  return <div className="forms-showcase-grid forms-showcase-grid--wide"><section className="forms-wizard-card"><div className="forms-wizard-card-heading"><div><p className="card-kicker">Pattern</p><h2>Progress bar</h2></div><span>Validated flow</span></div><header className="forms-wizard-header"><WizardProgress steps={steps} currentStep={step} ariaLabel="Signup progress" onStepChange={goToStep} /></header><form className="forms-wizard-form" noValidate onSubmit={handleNext}><div className="forms-wizard-body">
    {step === 1 ? <div className="forms-validation-grid"><Field label="Name"><TextInput value={values.name} onChange={(event) => update("name", event.target.value)} placeholder="John Smith" required aria-invalid={isInvalid("name")} aria-describedby="wizard-name-message" /><FieldMessage id="wizard-name-message" show={isInvalid("name")}>Please choose a name.</FieldMessage></Field><Field label="Email"><TextInput type="email" value={values.email} onChange={(event) => update("email", event.target.value)} placeholder="Email address" required aria-invalid={isInvalid("email")} aria-describedby="wizard-email-message" /><FieldMessage id="wizard-email-message" show={isInvalid("email")}>You must add a valid email.</FieldMessage></Field><Field label="Password"><TextInput type="password" value={values.password} onChange={(event) => update("password", event.target.value)} placeholder="At least 8 characters" required aria-invalid={isInvalid("password")} aria-describedby="wizard-password-message" /><FieldMessage id="wizard-password-message" show={isInvalid("password")}>Use at least eight characters.</FieldMessage></Field><Field label="Confirm password"><TextInput type="password" value={values.confirmPassword} onChange={(event) => update("confirmPassword", event.target.value)} placeholder="Repeat your password" required aria-invalid={isInvalid("confirmPassword")} aria-describedby="wizard-confirm-message" /><FieldMessage id="wizard-confirm-message" show={isInvalid("confirmPassword")}>Passwords need to match.</FieldMessage></Field><div className="forms-wizard-terms"><div className="forms-wizard-consent"><label className="forms-validation-check"><input type="checkbox" checked={values.terms} onChange={(event) => update("terms", event.target.checked)} aria-invalid={isInvalid("terms")} aria-describedby="wizard-terms-message" /><span>I accept the</span></label><Popover trigger={<button type="button" className="forms-wizard-terms-trigger">terms and privacy policy.</button>} title="Terms and privacy policy" ariaLabel="Terms and privacy policy"><p>Use your workspace responsibly. Your account data is protected and never shared without your permission.</p></Popover></div><FieldMessage id="wizard-terms-message" show={isInvalid("terms")}>You must accept before continuing.</FieldMessage></div></div> : null}
    {step === 2 ? <div className="forms-validation-grid"><div className="forms-wizard-upload"><TextInput type="file" aria-label="Upload profile picture" /><span>Upload a 300x300 JPG or PNG up to 400KB.</span></div><Field label="Gender"><CommandSelect ariaLabel="Gender" options={[{ label: "Choose gender", value: "" }, { label: "Female", value: "female" }, { label: "Male", value: "male" }, { label: "Other", value: "other" }]} value={values.gender} onChange={(value) => update("gender", value)} invalid={isInvalid("gender")} describedBy="wizard-gender-message" /><FieldMessage id="wizard-gender-message" show={isInvalid("gender")}>This field is required.</FieldMessage></Field><Field label="Phone"><TextInput type="tel" value={values.phone} onChange={(event) => update("phone", event.target.value)} placeholder="Phone" required aria-invalid={isInvalid("phone")} aria-describedby="wizard-phone-message" /><FieldMessage id="wizard-phone-message" show={isInvalid("phone")}>This field is required.</FieldMessage></Field><WizardDateField id="wizard-date-of-birth" label="Date of birth" value={values.dateOfBirth} onChange={(value) => update("dateOfBirth", value)} invalid={isInvalid("dateOfBirth")} describedBy="wizard-date-message" errorId="wizard-date-message" errorMessage="This field is required." /><Field label="Address"><textarea className="forms-input" rows={4} value={values.address} onChange={(event) => update("address", event.target.value)} required aria-invalid={isInvalid("address")} aria-describedby="wizard-address-message" /><FieldMessage id="wizard-address-message" show={isInvalid("address")}>This field is required.</FieldMessage></Field></div> : null}
    {step === 3 ? <div className="forms-validation-grid"><Field label="Card number"><TextInput inputMode="numeric" value={values.cardNumber} onChange={(event) => update("cardNumber", event.target.value)} placeholder="XXXX XXXX XXXX XXXX" required aria-invalid={isInvalid("cardNumber")} aria-describedby="wizard-card-number-message" /><FieldMessage id="wizard-card-number-message" show={isInvalid("cardNumber")}>Enter at least 12 digits.</FieldMessage></Field><Field label="Name on card"><TextInput value={values.cardName} onChange={(event) => update("cardName", event.target.value)} placeholder="John Doe" required aria-invalid={isInvalid("cardName")} aria-describedby="wizard-card-name-message" /><FieldMessage id="wizard-card-name-message" show={isInvalid("cardName")}>This field is required.</FieldMessage></Field><Field label="Country"><CommandSelect ariaLabel="Country" options={[{ label: "Choose country", value: "" }, { label: "United States", value: "united-states" }, { label: "Canada", value: "canada" }, { label: "United Kingdom", value: "united-kingdom" }]} value={values.country} onChange={(value) => update("country", value)} invalid={isInvalid("country")} describedBy="wizard-country-message" /><FieldMessage id="wizard-country-message" show={isInvalid("country")}>This field is required.</FieldMessage></Field><Field label="Zip"><TextInput inputMode="numeric" value={values.zip} onChange={(event) => update("zip", event.target.value)} placeholder="12345" required aria-invalid={isInvalid("zip")} aria-describedby="wizard-zip-message" /><FieldMessage id="wizard-zip-message" show={isInvalid("zip")}>Enter a valid five-digit zip.</FieldMessage></Field><WizardDateField id="wizard-expiration" label="Date of expire" value={values.expiration} onChange={(value) => update("expiration", value)} monthYear invalid={isInvalid("expiration")} describedBy="wizard-expiration-message" errorId="wizard-expiration-message" errorMessage="Use MM/YYYY." /><Field label="CVV"><TextInput inputMode="numeric" value={values.cvv} onChange={(event) => update("cvv", event.target.value)} placeholder="123" required aria-invalid={isInvalid("cvv")} aria-describedby="wizard-cvv-message" /><FieldMessage id="wizard-cvv-message" show={isInvalid("cvv")}>Enter a valid security code.</FieldMessage></Field></div> : null}
    {step === 4 ? <div className="forms-wizard-complete" role="status" aria-live="polite"><Check aria-hidden="true" /><h2>You are all set!</h2><p>Now you can access your workspace anytime, anywhere.</p></div> : null}
  </div><footer className="forms-wizard-footer"><Button type="button" appearance="outline" disabled={step === 1} onClick={handleBack}>Previous</Button>{step < 4 ? <Button type="submit">Next</Button> : <Button type="button" onClick={(event) => { event.preventDefault(); event.stopPropagation(); reset(); }}>Start over</Button>}</footer></form></section><WizardWithoutValidation /><VerticalValidationWizard /></div>;
}

function WizardWithoutValidation() {
  const steps = ["Details", "Preferences", "Review"];
  const [step, setStep] = useState(1);
  const [project, setProject] = useState("");
  const [timezone, setTimezone] = useState("UTC");
  const [notes, setNotes] = useState("");
  const move = (next: number) => setStep(Math.max(1, Math.min(3, next)));
  const reset = () => { setStep(1); setProject(""); setTimezone("UTC"); setNotes(""); };
  return <section className="forms-wizard-card forms-wizard-card--without-validation"><div className="forms-wizard-card-heading"><div><p className="card-kicker">Variant</p><h2>Without validation</h2></div><span>Flexible flow</span></div><header className="forms-wizard-header"><WizardProgress steps={steps} currentStep={step} ariaLabel="Project setup progress" onStepChange={move} /></header><form className="forms-wizard-form" onSubmit={(event) => { event.preventDefault(); move(step + 1); }}><div className="forms-wizard-body">{step === 1 ? <div className="forms-validation-grid"><Field label="Project name" hint="You can keep this blank and continue."><TextInput value={project} onChange={(event) => setProject(event.target.value)} placeholder="A new workspace" /></Field><Field label="Owner"><TextInput defaultValue="Yorupus" /></Field></div> : null}{step === 2 ? <div className="forms-validation-grid"><Field label="Timezone"><CommandSelect ariaLabel="Timezone" options={[{ label: "UTC", value: "UTC" }, { label: "Pacific time", value: "Pacific" }, { label: "Central European time", value: "CET" }]} value={timezone} onChange={setTimezone} /></Field><Field label="Notes"><textarea className="forms-input" rows={4} value={notes} onChange={(event) => setNotes(event.target.value)} placeholder="Optional context for collaborators" /></Field></div> : null}{step === 3 ? <div className="forms-wizard-review"><Check aria-hidden="true" /><h3>Ready to continue</h3><p>{project || "Your project"} will use {timezone} scheduling. You can still edit these details later.</p></div> : null}</div><footer className="forms-wizard-footer"><Button type="button" appearance="outline" disabled={step === 1} onClick={() => move(step - 1)}>Previous</Button>{step < 3 ? <Button type="submit">Next</Button> : <Button type="button" onClick={(event) => { event.preventDefault(); event.stopPropagation(); reset(); }}>Start over</Button>}</footer></form></section>;
}

function VerticalValidationWizard() {
  const steps = ["Workspace", "Team", "Review"];
  const [step, setStep] = useState(1);
  const [submitted, setSubmitted] = useState(false);
  const [values, setValues] = useState({ workspace: "", email: "", role: "", summary: "" });
  const update = <Key extends keyof typeof values>(key: Key, value: typeof values[Key]) => setValues((current) => ({ ...current, [key]: value }));
  const errors = step === 1 ? { workspace: !values.workspace.trim() } : step === 2 ? { email: !/^[^\s@]+@[^\s@]+\.[^\s@]+$/.test(values.email), role: !values.role } : {};
  const isInvalid = (field: string) => Boolean(submitted && errors[field as keyof typeof errors]);
  const handleNext = (event: React.FormEvent<HTMLFormElement>) => { event.preventDefault(); setSubmitted(true); if (Object.values(errors).some(Boolean)) return; setStep((current) => Math.min(3, current + 1)); setSubmitted(false); };
  const reset = () => { setStep(1); setSubmitted(false); setValues({ workspace: "", email: "", role: "", summary: "" }); };
  return <section className="forms-wizard-card forms-wizard-card--vertical"><div className="forms-wizard-card-heading"><div><p className="card-kicker">Variant</p><h2>Vertical validation</h2></div><span>Inline recovery</span></div><div className="forms-wizard-vertical-progress"><WizardProgress steps={steps} currentStep={step} ariaLabel="Workspace setup progress" onStepChange={(target) => { if (target < step) { setStep(target); setSubmitted(false); } }} /></div><div className="forms-wizard-vertical-layout"><nav className="forms-wizard-vertical-nav" aria-label="Workspace setup steps"><ol>{steps.map((label, index) => <li key={label} className={index + 1 === step ? "is-current" : index + 1 < step ? "is-complete" : ""}><button type="button" disabled={index + 1 > step} aria-current={index + 1 === step ? "step" : undefined} onClick={() => { if (index + 1 < step) { setStep(index + 1); setSubmitted(false); } }}><span className="forms-wizard-step-number">{index + 1 < step ? <Check aria-hidden="true" /> : index + 1}</span><span><b>{label}</b><small>{index === 0 ? "Name your space" : index === 1 ? "Invite your team" : "Confirm details"}</small></span></button></li>)}</ol></nav><form className="forms-wizard-form forms-wizard-vertical-form" noValidate onSubmit={handleNext}><div className="forms-wizard-body">{step === 1 ? <Field label="Workspace name"><TextInput value={values.workspace} onChange={(event) => update("workspace", event.target.value)} placeholder="YoruSpace" aria-invalid={isInvalid("workspace")} aria-describedby="vertical-workspace-message" /><FieldMessage id="vertical-workspace-message" show={isInvalid("workspace")}>Choose a workspace name to continue.</FieldMessage></Field> : null}{step === 2 ? <div className="forms-validation-grid"><Field label="Team email"><TextInput type="email" value={values.email} onChange={(event) => update("email", event.target.value)} placeholder="name@company.com" aria-invalid={isInvalid("email")} aria-describedby="vertical-email-message" /><FieldMessage id="vertical-email-message" show={isInvalid("email")}>Enter a valid email address.</FieldMessage></Field><Field label="Role"><CommandSelect ariaLabel="Role" options={[{ label: "Choose a role", value: "" }, { label: "Designer", value: "designer" }, { label: "Developer", value: "developer" }]} value={values.role} onChange={(value) => update("role", value)} invalid={isInvalid("role")} describedBy="vertical-role-message" /><FieldMessage id="vertical-role-message" show={isInvalid("role")}>Choose a role to continue.</FieldMessage></Field></div> : null}{step === 3 ? <div className="forms-wizard-review"><Check aria-hidden="true" /><h3>Everything is ready</h3><p>{values.workspace || "Your workspace"} will invite {values.email || "your teammate"} as a {values.role || "team member"}.</p><Field label="Optional summary"><textarea className="forms-input" rows={3} value={values.summary} onChange={(event) => update("summary", event.target.value)} placeholder="Add a note for the team" /></Field></div> : null}</div><footer className="forms-wizard-footer"><Button type="button" appearance="outline" disabled={step === 1} onClick={() => { setStep((current) => Math.max(1, current - 1)); setSubmitted(false); }}>Previous</Button>{step < 3 ? <Button type="submit">Next</Button> : <Button type="button" onClick={(event) => { event.preventDefault(); event.stopPropagation(); reset(); }}>Start over</Button>}</footer></form></div></section>;
}

export function FormShowcase({ kind }: { kind: FormShowcaseKind }) { const current = meta[kind]; const content = { "form-control": <FormControl />, "input-group": <InputGroup />, select: <Selects />, checks: <Checks />, range: <RangeExample />, "floating-labels": <FloatingLabels />, "form-layout": <FormLayout />, "advanced-select": <AdvancedSelect />, "date-picker": <DatePicker />, editor: <Editor />, "file-uploader": <FileUploader />, "advanced-range": <RangeExample advanced />, rating: <Rating />, "emoji-button": <EmojiButton />, validation: <Validation />, wizard: <Wizard /> }[kind]; return <main id="component-content" className="dashboard-main component-showcase forms-showcase"><header className="component-showcase-header"><p className="dashboard-eyebrow">Components <span>/</span> {current.trail} <span>/</span> {current.section}</p><h1>{current.title}</h1><p>{current.description}</p></header>{content}</main>; }
